// Generates src/canon-table.generated.ts from canon/confusables.txt (the single source of truth, shared with the
// Rust program's build.rs). Run:  node packages/shared/scripts/gen-canon.ts
// A test fails if the committed generated file is out of date.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));

export function parseConfusables(text: string): { version: number; pairs: [string, string][] } {
  let version: number | undefined;
  const pairs: [string, string][] = [];
  for (const [i, raw] of text.split("\n").entries()) {
    const line = raw.trim();
    if (line === "" || line.startsWith("#")) continue;
    const parts = line.split(/\s+/);
    if (parts.length === 2 && parts[0] === "version") version = Number(parts[1]);
    else if (parts.length === 2 && parts[0]!.length === 1 && parts[1]!.length === 1) pairs.push([parts[0]!.toUpperCase(), parts[1]!]);
    else throw new Error(`confusables.txt:${i + 1}: expected "version <n>" or "<from> <to>"`);
  }
  if (version === undefined || !Number.isInteger(version)) throw new Error("confusables.txt needs a version line");
  return { version, pairs };
}

export function renderGenerated(text: string): string {
  const { version, pairs } = parseConfusables(text);
  const entries = pairs.map(([from, to]) => `  ${JSON.stringify(from)}: ${JSON.stringify(to)},`).join("\n");
  return `// GENERATED by packages/shared/scripts/gen-canon.ts from canon/confusables.txt. Do not edit.\nexport const CANON_VERSION = ${version};\nexport const CONFUSABLES: Readonly<Record<string, string>> = {\n${entries}\n};\n`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const out = renderGenerated(readFileSync(`${root}canon/confusables.txt`, "utf8"));
  writeFileSync(`${root}src/canon-table.generated.ts`, out);
  console.log("wrote src/canon-table.generated.ts");
}
